import { useCallback, useContext, useEffect, useRef, useState } from 'react';

import type OpenFin from '@openfin/core';

import { getDefaultBrowserUrl } from '@common/utils/browser-base-url';
import { isWindowRunning } from '@common/utils/window';

import { BrowserTypeContext } from './context';

interface PreloadedWindowOptions {
    windowName: string;
    route: string;
    shouldPreload?: boolean;
    windowCreationOptions?: Partial<OpenFin.WindowCreationOptions>;
}

const getDefaultPreloadWindowCreationOptions = (isEnterprise: boolean): Partial<OpenFin.WindowCreationOptions> => {
    return {
        autoShow: false,
        frame: false,
        smallWindow: true,
        saveWindowState: false,
        includeInSnapshots: false,
        showTaskbarIcon: false,
        workspacePlatform: {
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            windowType: isEnterprise ? 'enterprise' : 'browser'
        },
        throttling: 'disabled',
        resizable: false
    };
};

export default function usePreloadedWindow({
    windowName,
    route,
    shouldPreload,
    windowCreationOptions
}: PreloadedWindowOptions) {
    const [windowInstance, setWindowInstance] = useState<OpenFin.Window | null>(null);
    // keep track of window creations so we don't try to create them multiple times
    const isCreated = useRef<boolean>(false);
    const isEnterprise = useContext(BrowserTypeContext).isEnterprise;

    const preload = useCallback(async () => {
        if (isCreated.current) return;
        isCreated.current = true;

        const popupIdentity = { name: windowName, uuid: fin.me.identity.uuid };

        try {
            if (await isWindowRunning(popupIdentity)) {
                return;
            }

            const opts: OpenFin.WindowCreationOptions = {
                ...getDefaultPreloadWindowCreationOptions(isEnterprise),
                ...windowCreationOptions,
                name: windowName,
                url: (await getDefaultBrowserUrl(isEnterprise)) + route
            };
            console.debug(`[usePreloadedWindow] creating preloaded window ${windowName} with options`, opts);
            const win = await fin.Platform.getCurrentSync().createWindow(opts);
            setWindowInstance(win);
        } catch (e) {
            console.error(`[usePreloadedWindow] Error creating ${windowName}, silently continuing`);
            // before resetting, double check if the window succeeded somewhere else
            if (!(await isWindowRunning(popupIdentity))) {
                isCreated.current = false;
            }
        }
    }, [route, windowCreationOptions, windowName, isCreated, isEnterprise]);

    useEffect(() => {
        if (!windowInstance && shouldPreload) {
            preload();
        }
    }, [windowInstance, shouldPreload, preload]);

    return windowInstance;
}
