import React, { PropsWithChildren } from 'react';

import { Size } from '@openfin/ui-library';

import { BaseCustomButtonStyleProps } from '@common/utils/base-button-props';

import { BaseCustomButtonConfig } from '@client/shapes';

import BaseButton from '../BaseButton/BaseButton';
import { CustomIcon } from '../Icon/CustomIcon';

export interface BaseCustomButtonProps extends BaseCustomButtonConfig, BaseCustomButtonStyleProps {
    onClick?: (event: React.MouseEvent) => void;
    onContextMenu?: (event: React.MouseEvent) => void;
}

/**
 * A stylized button that is shared between workspace components and browser.
 */
const BaseCustomButton = React.forwardRef<HTMLButtonElement, PropsWithChildren<BaseCustomButtonProps>>(
    (
        {
            tooltip,
            iconUrl,
            disabled,
            usePlaceholder,
            onClick,
            onContextMenu,
            rounded,
            selected,
            children,
            size,
            ...props
        },
        ref
    ) => (
        <BaseButton
            ref={ref}
            onClick={onClick}
            title={tooltip}
            onContextMenu={onContextMenu}
            disabled={disabled}
            borderRadius={rounded ? Size.xsmall : undefined}
            selected={selected}
            customContentSize={!!size}
            {...props}
        >
            {iconUrl && <CustomIcon iconURL={iconUrl} size={size} description={usePlaceholder ? tooltip : undefined} />}
            {children}
        </BaseButton>
    )
);

BaseCustomButton.displayName = 'BaseCustomButton';

export default BaseCustomButton;
