import { OpenFin } from '@openfin/core';

import { workspaceBuildVersion } from '@common/utils/env';
import { showSwitchWorkspaceSuccess } from '@common/utils/indicators/showIndicator';
import LocalStorageKey from '@common/utils/local-storage-key';
import * as namespacedLocalStorage from '@common/utils/namespaced-local-storage';
import { randomUUID } from '@common/utils/uuid';
import { currentOFIdentity, WindowName } from '@common/utils/window';
import { showRestoreChangesModal, showSwitchWorkspaceModal } from '@common/utils/workspace-modals';

import {
    getWorkspacePlatformChannelClient,
    WorkspacePlatformChannelAction
} from '@common/api/protocol/workspace-platform';

import { DOCK3_WINDOW_NAME } from '@dock3/api/constants';

import { getCurrentSync } from '@client-platform/index';
import { getIsEnterprisePlatform } from '@client-platform/init/enterprise';
import type {
    ApplyWorkspacePayload,
    CreateSavedWorkspaceRequest,
    GetCurrentWorkspaceOptions,
    RestoreLastSavedWorkspacePayload,
    RestoreLastSavedWorkspaceResult,
    Workspace
} from '@client-platform/shapes';

import { handleNameCollision } from '../name-collisions';

async function applyWorkspaceInternal({ options, ...workspace }: ApplyWorkspacePayload): Promise<boolean> {
    const shouldSwitchWorkspaces = options?.skipPrompt
        ? true
        : await showSwitchWorkspaceModal(
              options?.promptContainerWindowIdentity,
              workspace.title,
              options?.shouldCenterModalOnMonitor
          );

    if (!shouldSwitchWorkspaces) return false;

    const applicationWindows = await fin.Application.getCurrentSync().getChildWindows();
    const dock3WindowExists = !!applicationWindows.find(
        ({ identity }: OpenFin.Window) =>
            identity.name === WindowName.DockCompanion || identity.name === DOCK3_WINDOW_NAME
    );

    // If we're restoring a workspace but we're using Dock 3, use closeSnapshotWindows instead of closeExistingWindows.
    // This prevents losing Dock 3 in EB/WAAS environments, but preserves behavior for Workspace customers.
    const applyWorkspaceSettings =
        dock3WindowExists || getIsEnterprisePlatform()
            ? {
                  closeExistingWindows: false,
                  closeSnapshotWindows: true
              }
            : { closeExistingWindows: options?.applySnapshotOptions?.closeExistingWindows ?? true };

    const platform = getCurrentSync();

    await platform.applySnapshot(workspace.snapshot, {
        ...(options?.applySnapshotOptions ?? {}),
        ...applyWorkspaceSettings
    });

    setActiveWorkspace(workspace);
    showSwitchWorkspaceSuccess().catch(console.warn);
    return true;
}

/**
 * Apply the given workspace and set it as active.
 * @param payload, the workspace to apply and the options to apply it with.
 *
 * @returns true if the workspace was applied, false if the user cancelled the switch or an error occurred.
 */
export async function applyWorkspace(payload: ApplyWorkspacePayload): Promise<boolean> {
    try {
        return await applyWorkspaceInternal(payload);
    } catch (err) {
        console.error('failed to apply the current workspace: ', err);
        return false;
    }
}

export async function restoreLastSavedWorkspaceInternal(
    options?: RestoreLastSavedWorkspacePayload
): Promise<RestoreLastSavedWorkspaceResult> {
    try {
        const lastWorkspace = await getLastSavedWorkspace();
        if (!lastWorkspace) {
            return 'not-saved-workspace';
        }
        const shouldRestore = options?.skipPrompt
            ? true
            : await showRestoreChangesModal(options?.promptContainerWindowIdentity);

        if (!shouldRestore) return 'user-declined';

        await applyWorkspaceInternal({
            options: {
                skipPrompt: true,
                applySnapshotOptions: options?.applySnapshotOptions
            },
            ...lastWorkspace
        });

        return 'success';
    } catch (err) {
        console.error('failed to restore last saved workspace: ', err);
        throw err;
    }
}

/**
 * Set the current active workspace.
 */
export function setActiveWorkspace(workspace: Workspace) {
    if (typeof localStorage === 'undefined') return;
    try {
        const currentWorkspace = JSON.stringify(workspace);
        namespacedLocalStorage.setItem(LocalStorageKey.CurrentWorkspaceId, currentWorkspace);
    } catch (err) {
        console.error('failed to set the active workspace: ', err);
    }
}

/**
 * Get the initial workspace data structure that represents the an untitled empty workspace.
 * @returns the current active workspace.
 */
export async function getInitialWorkspace(): Promise<Workspace> {
    const platform = getCurrentSync();
    const snapshot = await platform.getSnapshot();
    return {
        workspaceId: randomUUID(),
        title: await getUniqueWorkspaceTitle(),
        metadata: { APIVersion: workspaceBuildVersion },
        snapshot
    };
}

/**
 * Get a workspace data structure that represents the users current desktop.
 * @returns the current active workspace.
 */
export async function getCurrentWorkspace(options?: GetCurrentWorkspaceOptions): Promise<Workspace> {
    if (typeof localStorage === 'undefined') {
        return getInitialWorkspace();
    }
    const currentWorkspaceString = namespacedLocalStorage.getItem(LocalStorageKey.CurrentWorkspaceId);
    if (!currentWorkspaceString) {
        // Getting initial when current does not exist in case local storage gets cleared somehow
        return getInitialWorkspace();
    }
    const currentWorkspace = JSON.parse(currentWorkspaceString);
    if (options?.skipSnapshotUpdate) {
        return currentWorkspace;
    }
    const platform = getCurrentSync();
    const snapshot = await platform.getSnapshot();
    return {
        ...currentWorkspace,
        metadata: { APIVersion: workspaceBuildVersion },
        snapshot
    };
}

export async function getLastSavedWorkspace(): Promise<Workspace | undefined> {
    const platform = getCurrentSync();
    const activeWorkspace = await platform.getCurrentWorkspace({ skipSnapshotUpdate: true });
    const savedWorkspaces = await platform.Storage.getWorkspaces();

    return savedWorkspaces.find((workspace) => workspace.workspaceId === activeWorkspace.workspaceId);
}

export const createWorkspaceInStorage = async (req: CreateSavedWorkspaceRequest) => {
    const client = await getWorkspacePlatformChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.CreateSavedWorkspace, req);
};

export const getWorkspacesInStorage = async (): Promise<Workspace[]> => {
    const client = await getWorkspacePlatformChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.GetSavedWorkspaces, undefined);
};

export const getWorkspaceInStorage = async (id: string): Promise<Workspace> => {
    const client = await getWorkspacePlatformChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.GetSavedWorkspace, id);
};

export const deleteWorkspaceInStorage = async (id: string) => {
    const client = await getWorkspacePlatformChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.DeleteSavedWorkspace, id);
};

const updateWorkspaceInStorage = async (req: { workspaceId: string; workspace: Workspace }) => {
    const client = await getWorkspacePlatformChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.UpdateSavedWorkspace, req);
};

export const markUnsavedPagesAsSaved = async () => {
    const client = await getWorkspacePlatformChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.MarkUnsavedPagesAsSavedInternal, undefined);
};

export const saveWorkspace = async (workspace: Workspace) => {
    const savedWorkspace = await getWorkspaceInStorage(workspace.workspaceId);

    if (savedWorkspace) {
        return updateWorkspaceInStorage({ workspaceId: workspace.workspaceId, workspace });
    }
    return createWorkspaceInStorage({ workspace });
};

/**
 * Checks if a given workspace name is unique
 * If not, add a progressive number to it
 * @param initialName The initial name to test
 * @returns string: a unique workspace name
 */
export async function getUniqueWorkspaceTitle(initialName = 'Untitled Workspace'): Promise<string> {
    const workspaces = await getWorkspacesInStorage();

    // Names need to be unique across all running and saved pages
    const allWorkspaceNames = workspaces.map(({ title }) => title);

    return handleNameCollision(initialName, allWorkspaceNames);
}
